import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.16qmHapV.js";const m=JSON.parse('{"title":"PAI Content Hash","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"spec/hash.md","filePath":"spec/hash.md"}'),n={name:"spec/hash.md"};function o(r,e,h,c,d,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="pai-content-hash" tabindex="-1">PAI Content Hash <a class="header-anchor" href="#pai-content-hash" aria-label="Permalink to &quot;PAI Content Hash&quot;">​</a></h1><p>2026-11-09 · Draft 1 · Algorithm identifier: <code>pai-content-sha256-v1</code></p><p>The content hash identifies document fields and original image bytes independently of file packaging. The same document saved as <code>.pai</code> and <code>.pai.html</code> has the same content hash. ZIP compression settings and the HTML editor runtime are excluded.</p><p>The output is a string of 64 lowercase hexadecimal characters. Equality refers to the fields and bytes retained by the algorithm below. A textual edit changes the hash even when the meaning is similar. New publication snapshots use this algorithm; legacy snapshots retain their recorded algorithm and digest.</p><p>The <a href="/pai-website/spec/#conformance-language">conformance language</a> applies to this specification.</p><h2 id="algorithm" tabindex="-1">Algorithm <a class="header-anchor" href="#algorithm" aria-label="Permalink to &quot;Algorithm&quot;">​</a></h2><p>Implementations MUST perform these operations and produce the same digest for the same input:</p><ol><li>Parse and validate a content-model <code>0.6</code> document according to <a href="/pai-website/spec/format.html">FORMAT.md</a>. For HTML, read the <code>pai-data</code> element. For ZIP, read the <code>document</code> member of <code>document.json</code>.</li><li>Load the original bytes of every asset. Strictly decode HTML <code>data</code> as Base64, or read the ZIP entry named by <code>path</code>. If <code>bytes</code> is present, verify it against the actual length. Include assets that are not currently referenced by text or backgrounds.</li><li>Copy the complete document. Replace each asset object with <code>mime</code>, its optional <code>name</code>, the actual <code>bytes</code>, and <code>sha256</code>, the lowercase hexadecimal SHA-256 digest of the asset bytes. Remove <code>data</code> or <code>path</code>. Preserve an absent <code>name</code> as absent and an empty name as an empty string. Preserve all other document fields, including background-image <code>alt</code> text.</li><li>Serialize this object using the <a href="https://www.rfc-editor.org/rfc/rfc8785.html" target="_blank" rel="noreferrer">JSON Canonicalization Scheme, RFC 8785</a>. Object keys are ordered by UTF-16 code units; arrays retain their order. Numbers use ECMAScript JSON number serialization. Strings are not Unicode-normalized. Duplicate member names, non-finite numbers, and unpaired surrogates are invalid input.</li><li>Calculate SHA-256 over the canonical JSON&#39;s UTF-8 bytes and encode the result as 64 lowercase hexadecimal characters.</li></ol><p>Publication metadata MUST carry both <code>contentHashAlgorithm: &quot;pai-content-sha256-v1&quot;</code> and the resulting <code>contentHash</code> for new snapshots.</p><p>An asset&#39;s normalized form has the following shape:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image/png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;poster.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;bytes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1234</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sha256&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;64 lowercase hexadecimal characters&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The digest string above is a placeholder. <a href="/pai-website/spec/fixtures/hashes.json">fixtures/hashes.json</a> contains complete canonical JSON strings and expected digests for the fixed documents.</p><h2 id="effects-of-changes" tabindex="-1">Effects of changes <a class="header-anchor" href="#effects-of-changes" aria-label="Permalink to &quot;Effects of changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>Result</th></tr></thead><tbody><tr><td>Reorder JSON object keys; replace the HTML runtime; change ZIP compression or entry order</td><td>Same hash</td></tr><tr><td>Convert between <code>.pai</code> and <code>.pai.html</code>, preserving fields and original bytes</td><td>Same hash</td></tr><tr><td>Add an accurate optional <code>bytes</code> field or remove it</td><td>Same hash; normalization uses the actual length</td></tr><tr><td>Change text, reading order, layout, asset name, image bytes, document ID, or revision</td><td>Different hash</td></tr><tr><td>Change only the document revision</td><td>Different hash</td></tr></tbody></table><p>Unreferenced assets remain part of the hash. Packaging-only conversion MUST preserve them. Removing an asset is a content edit.</p><h2 id="legacy-snapshots" tabindex="-1">Legacy snapshots <a class="header-anchor" href="#legacy-snapshots" aria-label="Permalink to &quot;Legacy snapshots&quot;">​</a></h2><p>The <code>0.0.6</code> service hashed the complete document object, including Base64 asset data, after recursively sorting object keys. This historical algorithm is identified as <code>pai-json-sha256-v0.6</code>. Existing snapshot hashes MUST remain unchanged. A historical response without an algorithm field is interpreted according to its declared <code>0.0.6</code> contract.</p><p>When loading a legacy record, a server MUST preserve the stored digest and snapshot. To determine whether a retry in another packaging represents the same content, the server MAY normalize both documents with the new algorithm. A successful retry MUST return the original publication record, including its original hash and algorithm. New snapshots MUST use <code>pai-content-sha256-v1</code>. Existing version identifiers and source URLs MUST continue to identify the original snapshots.</p><h2 id="implementation-note" tabindex="-1">Implementation note <a class="header-anchor" href="#implementation-note" aria-label="Permalink to &quot;Implementation note&quot;">​</a></h2><p>The Node file tools, CLI, and reference content service implement this algorithm. The browser editor preserves all assets when saving either representation; the CLI can compare the resulting hashes. The editor currently has no whole-document hash command.</p><p>The reference file API keeps assets as binary buffers. <code>contentFingerprint()</code> constructs the normalized metadata and asset digests directly from that representation. Base64 encoding and copying image buffers are unnecessary for the current hash calculation. The resulting digest still follows the algorithm and fixed vectors above.</p><p>The historical <code>pai-json-sha256-v0.6</code> calculation retains its Base64 document representation. Reference clients and the service use <code>toJSONDocument()</code> at that boundary before canonical serialization. The in-memory representation does not create a new hash algorithm.</p><p>The local file tools migrate historical HTML content models <code>0.4</code> and <code>0.5</code> to <code>0.6</code> before calculating this hash. The migration is an implementation facility; service publication accepts the content versions declared in discovery.</p><p>The <a href="https://github.com/JacenDu/pai-protocol/blob/main/development/reports/ALPHA-ACCEPTANCE.md" target="_blank" rel="noreferrer">Alpha acceptance record</a> describes conversion, service, and release checks.</p>`,24)])])}const g=t(n,[["render",o]]);export{m as __pageData,g as default};
